const BASE = 'http://localhost:5000/api';

export async function fetchStats()         { const r = await fetch(`${BASE}/stats`);                    return r.json(); }
export async function fetchTraders()       { const r = await fetch(`${BASE}/traders`);                  return r.json(); }
export async function fetchTrades(p = 1)   { const r = await fetch(`${BASE}/trades?page=${p}&limit=50`);return r.json(); }
export async function fetchFraudCycles()   { const r = await fetch(`${BASE}/fraud/cycles`);             return r.json(); }
export async function fetchRiskLogs()      { const r = await fetch(`${BASE}/fraud/logs`);               return r.json(); }
export async function fetchFraudLogs()     { const r = await fetch(`${BASE}/fraud/logs`);               return r.json(); }
export async function fetchTraderById(id)  { const r = await fetch(`${BASE}/traders/${id}`);            return r.json(); }
export async function fetchStocks()        { const r = await fetch(`${BASE}/stocks`);                   return r.json(); }
export async function insertTrade(data)    { const r = await fetch(`${BASE}/trades`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); return r.json(); }
